 else{const chance=state.upgrades.scanner?.1:.035;if(Math.random()<chance){const id=String(100+rand(899));state.drives.push({id,trueDrive:false,checked:false});state.totalDrives++;log(`USB-${id} recovered in the debris.`);toast('USB DRIVE RECOVERED');}}
